-- Pharmacy claim history: reversal-aware claims, projected manual fills,
-- and pharmacy-confirmed pickups as their own records.
--
-- 1. pharmacy_pickup_confirmations: one row per pickup the pharmacy
--    confirmed (date, source, who logged it), kept apart from claim data.
--    Readable by signed-in users only, like the other patient tables.
-- 2. Sample pickups for the demo members.
-- 3. Demo members 19401-19410: claims carry transaction fields (type,
--    sequence, reversal link, processed date, coverage, BIN / PCN / group),
--    prior-year PDC, and one measure per claim scenario:
--      19401 MAD  paid claim matching a confirmed pickup (Closed-Data)
--      19403 MAC  claim reversed after the fill went back to stock
--      19403 MAD  resubmitted claim (sequence 2 is current)
--      19404 MAH  reversal sent as negative quantity / days supply
--      19405 MAC  fill entered by hand, no claim (Claim not matched)
--      19406 MAH  fill entered by hand, claim billed to commercial coverage
--      19407 MAD  confirmed pickup, claim not arrived yet (Completed)
--    Generated from src/features/pharmacy-worklist/data/mock.js.
--    Replacing `measures` resets demo work stored on the gaps (manual
--    statuses, confirmed fills); 19407 also gets its pickup call.
--
-- Safe to run more than once.

begin;

create table if not exists public.pharmacy_pickup_confirmations (
  id            text primary key,
  member_row_id text not null references public.pharmacy_worklist_members(id) on delete cascade,
  measure_code  text not null,
  pickup_date   text not null,
  source        text not null,
  logged_by     text,
  logged_at     timestamptz not null default now(),
  note          text
);
create index if not exists pharmacy_pickup_confirmations_member_idx
  on public.pharmacy_pickup_confirmations (member_row_id, measure_code);

alter table public.pharmacy_pickup_confirmations enable row level security;
drop policy if exists "Authenticated full access to pharmacy_pickup_confirmations" on public.pharmacy_pickup_confirmations;
create policy "Authenticated full access to pharmacy_pickup_confirmations"
  on public.pharmacy_pickup_confirmations for all to authenticated
  using (true) with check (true);

insert into public.pharmacy_pickup_confirmations (id, member_row_id, measure_code, pickup_date, source, logged_by, logged_at, note)
select v.id, v.member_row_id, v.measure_code, v.pickup_date, v.source, v.logged_by, v.logged_at::timestamptz, v.note
from (values
  ('pu-19401-mad-10092026', '19401', 'MAD', '10/09/2026', 'Pharmacy call', 'Priya Natarajan', '2026-10-09T17:10:00.000Z', null),
  ('pu-19402-mac-09222026', '19402', 'MAC', '09/22/2026', 'Pharmacy call', 'Priya Natarajan', '2026-09-22T17:11:00.000Z', null),
  ('pu-19406-mad-09302026', '19406', 'MAD', '09/30/2026', 'Pharmacy verification', 'Marcus Reyes', '2026-09-30T17:12:00.000Z', null),
  ('pu-19407-mad-10182026', '19407', 'MAD', '10/18/2026', 'Pharmacy call', 'Priya Natarajan', '2026-10-18T17:13:00.000Z', 'Picked up at the counter; claim not on the plan feed yet.'),
  ('pu-19408-mad-10012026', '19408', 'MAD', '10/01/2026', 'Pharmacy call', 'Marcus Reyes', '2026-10-01T17:14:00.000Z', null),
  ('pu-19409-mac-09242026', '19409', 'MAC', '09/24/2026', 'Pharmacy verification', 'Priya Natarajan', '2026-09-24T17:15:00.000Z', null)
) as v(id, member_row_id, measure_code, pickup_date, source, logged_by, logged_at, note)
where exists (select 1 from public.pharmacy_worklist_members as m where m.id = v.member_row_id)
on conflict (id) do nothing;

update public.pharmacy_worklist_members as m
set measures = v.measures,
    call_history = case when m.id = '19407' then v.call_history else m.call_history end,
    status_manual = false
